import { ARENA_LIGHTING } from "../arena-lighting";
import { compileMap } from "../maps/registry";
import type { MapDefinition } from "../maps/types";
import {
  SANDGATE_BOMBSITES,
  SANDGATE_BOXES,
  SANDGATE_SIZE,
  SANDGATE_TEAM_SPAWNS,
  SANDGATE_WALLS,
} from "../sandgate-layout";

/**
 * MAP 06 (working name SANDGATE): the 5v5 Practice Bomb Defusal map. Gameplay solids, bombsites
 * and team spawns are generated by art/blender/map06/layout.py; design and research notes are in
 * docs/fps-bomb/DESIGN.md.
 *
 * Not in the 1v1 catalog (maps/catalog.ts) on purpose: the 1v1 rooms accept any catalog id, and
 * this map must only ever be played by the Bomb Defusal mode. It is compiled here with the same
 * compileMap() every catalog map uses, so collision, tracing and visibility are identical.
 */
export const SANDGATE_DEFINITION: MapDefinition = {
  id: "sandgate",
  name: "Sandgate",
  rotation: false,
  arena: SANDGATE_SIZE,
  boxes: SANDGATE_BOXES,
  structures: [],
  walls: SANDGATE_WALLS,
  barriers: [],
  floorSurface: "concrete",
  footsteps: { floor: "concrete" },
  // The 1v1 seats are unused here; Police and Terrorist spawns are SANDGATE_TEAM_SPAWNS.
  spawns: { A: SANDGATE_TEAM_SPAWNS.police[2], B: SANDGATE_TEAM_SPAWNS.terrorist[2] },
  // The 1v1 practice bot never plays this map (bomb bots have their own planner).
  bot: {
    openings: { center: [{ x: 0, z: 0 }], north: [{ x: 0, z: 0 }], south: [{ x: 0, z: 0 }] },
    sweep: [{ x: 0, z: 0 }],
    flanks: { north: [{ x: 0, z: 0 }], south: [{ x: 0, z: 0 }] },
    regroup: [{ x: 0, z: 0 }],
  },
  presentation: {
    modelUrl: "/fps/models/sandgate.glb?v=d5ea70d9b92c",
    // Clear early-afternoon desert sun from the south-west (46° high): sunlit sand-coloured
    // walls, crisp but not black shade in the lanes, warm ground bounce in the hemisphere term.
    // The sun sits 90 m out so the static shadow frustum (near 1 m) holds the whole 80 × 80 m
    // map and its 8–16 m rooftops; the extent covers the map's diagonal seen from the sun.
    lighting: {
      ...ARENA_LIGHTING,
      background: 0xaec8de,
      fog: { color: 0xdfcfb4, near: 85, far: 320 },
      hemisphere: { sky: 0xd6dbe0, ground: 0xa9895f, intensity: 1.3 },
      sun: { color: 0xfff0d6, intensity: 3.0, position: [-47, 64, 40] },
      environmentIntensity: 0.4,
      exposure: 1.0,
    },
    sky: { zenith: 0x4a80c2, horizon: 0xd3dde3, haze: 0xeadbc0 },
    shadow: { extent: 56, far: 170, mapSize: 2048 },
    viewDistance: 260,
    blockout: { concrete: 0xd2bb93, metal: 0x6f7559, wood: 0x8a6a45, floor: 0xc4ab82 },
  },
};

export const SANDGATE = compileMap(SANDGATE_DEFINITION);
export const SANDGATE_SITES = SANDGATE_BOMBSITES;
export const SANDGATE_SPAWNS = SANDGATE_TEAM_SPAWNS;
export type Bombsite = keyof typeof SANDGATE_BOMBSITES;

/** The bombsite whose plant zone contains the feet at (x, z), if any. */
export function bombsiteAt(x: number, z: number): Bombsite | null {
  for (const [site, r] of Object.entries(SANDGATE_BOMBSITES) as [
    Bombsite,
    (typeof SANDGATE_BOMBSITES)[Bombsite],
  ][])
    if (x >= r.x0 && x <= r.x1 && z >= r.z0 && z <= r.z1) return site;
  return null;
}
